<!DOCTYPE html>
<html lang="pt-br">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Portal de Eventos</title>
  <link rel="stylesheet" href="style.css">
</head>
<body>
  <div class="container">

    <!-- Tela de Login/Cadastro -->
    <div id="auth-section">
      <h1>Bem-vindo ao Portal de Eventos</h1>
      <div class="form-toggle">
        <button id="show-login-btn" class="active">Entrar</button>
        <button id="show-register-btn">Cadastre-se</button>
      </div>

      <!-- Formulário de Login -->
      <form id="login-form" class="auth-form">
        <h2>Login</h2>
        <input type="email" id="login-email" placeholder="E-mail" required>
        <input type="password" id="login-password" placeholder="Senha" required>
        <button type="submit">Entrar</button>
      </form>

      <!-- Formulário de Cadastro -->
      <form id="register-form" class="auth-form" style="display: none;">
        <h2>Criar Conta</h2>
        <input type="text" id="register-name" placeholder="Nome completo" required>
        <input type="email" id="register-email" placeholder="E-mail" required>
        <input type="password" id="register-password" placeholder="Senha" required>
        <select id="register-role">
          <option value="participante">Sou Participante</option>
          <option value="organizador">Sou Organizador</option>
        </select>
        <button type="submit">Cadastrar</button>
      </form>
    </div>

    <!-- Painel Principal (após login) -->
    <div id="main-section" style="display: none;">
      <header>
        <h2 id="welcome-message"></h2>
        <button id="logout-btn">Sair</button>
      </header>

      <!-- Visão do Participante -->
      <div id="participant-view">
        <div class="tabs">
          <button class="tab-link active" data-tab="available-events">Eventos Disponíveis</button>
          <button class="tab-link" data-tab="my-registrations">Minhas Inscrições</button>
        </div>
        <div id="available-events" class="tab-content active">
          <h3>Eventos Abertos para Inscrição</h3>
          <div id="events-list"></div>
        </div>
        <div id="my-registrations" class="tab-content">
          <h3>Eventos em que estou inscrito</h3>
          <div id="my-registrations-list"></div>
        </div>
      </div>

      <!-- Visão do Organizador -->
      <div id="organizer-view" style="display: none;">
        <div class="tabs">
          <button class="tab-link active" data-tab="manage-events">Gerenciar Eventos</button>
          <button class="tab-link" data-tab="create-event">Criar Evento</button>
        </div>
        <div id="manage-events" class="tab-content active">
          <h3>Todos os Eventos</h3>
          <div id="admin-events-list"></div>
        </div>
        <div id="create-event" class="tab-content">
          <h3 id="form-title">Criar Novo Evento</h3>
          <form id="event-form">
            <input type="hidden" id="event-id">
            <input type="text" id="event-title" placeholder="Título do Evento" required>
            <textarea id="event-description" placeholder="Descrição" required></textarea>
            <input type="datetime-local" id="event-date" required>
            <input type="text" id="event-location" placeholder="Local" required>
            <button type="submit">Salvar Evento</button>
            <button type="button" id="cancel-edit-btn" style="display: none;">Cancelar Edição</button>
          </form>
        </div>
      </div>
    </div>
  </div>

  <!-- Modal para ver inscrições -->
  <div id="registrations-modal" class="modal">
    <div class="modal-content">
      <span class="close-btn">&times;</span>
      <h3 id="modal-event-title"></h3>
      <table id="registrations-table">
        <thead>
          <tr>
            <th>Nome</th>
            <th>E-mail</th>
            <th>Status</th>
            <th>Ação</th>
          </tr>
        </thead>
        <tbody></tbody>
      </table>
    </div>
  </div>

  <script src="app.js"></script>
</body>
</html>
```

